#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::PathBuf;
use std::sync::Arc;

use faer::{Col, Mat};
use mopt_rs::core_infra::json::JsonValue;
use mopt_rs::domain::{positions, Bohr, Element, MolecularSystem, SpinCharge};
use mopt_rs::irc::{
    lqa_step, most_abundant_isotope_masses, BranchAction, BranchEnd, BranchStart, DwiSurface,
    IntegratorRegistry, IrcSettings, IrcSpace, PointRole, PointValue, TaylorPoint,
};

fn golden() -> JsonValue {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/golden/irc_parts.json");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    JsonValue::parse(&text).unwrap()
}

fn floats(v: &JsonValue) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .flat_map(|x| match x.as_array() {
            Some(inner) => inner
                .iter()
                .map(|y| y.as_f64().unwrap())
                .collect::<Vec<_>>(),
            None => vec![x.as_f64().unwrap()],
        })
        .collect()
}

fn col(v: &[f64]) -> Col<f64> {
    Col::from_fn(v.len(), |i| v[i])
}

fn square(v: &[f64]) -> Mat<f64> {
    let n = (v.len() as f64).sqrt().round() as usize;
    Mat::from_fn(n, n, |i, j| v[i * n + j])
}

fn system(coords_bohr: &[f64]) -> MolecularSystem {
    let elements: Vec<Element> = ["C", "N", "H"]
        .iter()
        .map(|s| Element::parse_token(s).unwrap())
        .collect();
    let pos: Vec<[f64; 3]> = coords_bohr.chunks(3).map(|c| [c[0], c[1], c[2]]).collect();
    MolecularSystem::new(
        elements,
        &positions::<Bohr>(&pos),
        SpinCharge::default(),
        None,
    )
    .unwrap()
}

fn largest_difference(a: &[f64], b: &[f64]) -> f64 {
    assert_eq!(a.len(), b.len());
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0, f64::max)
}

/// The space of the structure with the masses MultiOptPy's IRC uses (the most abundant
/// isotopes).
fn space(sys: &MolecularSystem, g: &JsonValue) -> IrcSpace {
    let masses = most_abundant_isotope_masses(sys).unwrap();
    assert_eq!(masses, floats(g.get("masses").unwrap()));
    IrcSpace::molecule_with_masses(sys, &masses, true).unwrap()
}

#[test]
fn lqa_step_matches_multioptpy() {
    let g = golden();
    let cases = g.get("lqa_steps").unwrap().as_array().unwrap();
    assert_eq!(cases.len(), 4);
    for case in cases {
        let step_size = case.get("step_size").unwrap().as_f64().unwrap();
        let geometry = floats(case.get("geometry").unwrap());
        let sys = system(&geometry);
        let space = space(&sys, &g);
        let dq = lqa_step(
            &square(&floats(case.get("mw_hessian").unwrap())),
            &col(&floats(case.get("mw_gradient").unwrap())),
            step_size,
            1e-8,
        )
        .unwrap();
        // MultiOptPy: the step divided by the square roots of the masses, then the centre
        // of mass moved to the origin.
        let new = space.displaced(&col(&geometry), &dq);
        let new: Vec<f64> = new.iter().copied().collect();
        let difference = largest_difference(&new, &floats(case.get("new_geometry").unwrap()));
        assert!(difference < 1e-10, "step size {step_size}: {difference}");
        // The step is not a trivial one.
        let moved = largest_difference(&new, &geometry);
        assert!(moved > 1e-3, "{moved}");
    }
}

fn taylor(v: &JsonValue) -> TaylorPoint {
    TaylorPoint {
        x: col(&floats(v.get("x").unwrap())),
        energy: v.get("energy").unwrap().as_f64().unwrap(),
        gradient: col(&floats(v.get("gradient").unwrap())),
        hessian: square(&floats(v.get("hessian").unwrap())),
    }
}

#[test]
fn interpolant_and_corrector_match_multioptpy() {
    let g = golden();
    for (k, case) in g.get("dwi").unwrap().as_array().unwrap().iter().enumerate() {
        let first = taylor(case.get("first").unwrap());
        let start = first.x.clone();
        let surface = DwiSurface::new(first, taylor(case.get("second").unwrap()));
        for probe in case.get("probes").unwrap().as_array().unwrap() {
            let x = col(&floats(probe.get("x").unwrap()));
            let energy = probe.get("energy").unwrap().as_f64().unwrap();
            assert!((surface.energy(&x) - energy).abs() < 1e-12 * energy.abs().max(1.0));
            let gradient: Vec<f64> = surface.gradient(&x).iter().copied().collect();
            let difference = largest_difference(&gradient, &floats(probe.get("gradient").unwrap()));
            assert!(difference < 1e-11, "case {k}: {difference}");
        }
        let length = case.get("descent_length").unwrap().as_f64().unwrap();
        let steps = case.get("descent_steps").unwrap().as_usize().unwrap();
        let end: Vec<f64> = surface
            .descend(&start, length, steps)
            .iter()
            .copied()
            .collect();
        let difference = largest_difference(&end, &floats(case.get("descent_end").unwrap()));
        assert!(difference < 1e-10, "case {k}: corrector {difference}");
    }
}

/// The Morse potential of the reference run: pairs `(i, j, D, a, r0)`.
fn morse(pairs: &[Vec<f64>], x: &Col<f64>) -> PointValue {
    let mut energy = 0.0;
    let mut gradient = Col::<f64>::zeros(x.nrows());
    for p in pairs {
        let (i, j) = (p[0] as usize, p[1] as usize);
        let (d, a, r0) = (p[2], p[3], p[4]);
        let v: Vec<f64> = (0..3).map(|c| x[3 * i + c] - x[3 * j + c]).collect();
        let r = v.iter().map(|c| c * c).sum::<f64>().sqrt();
        let e = (-a * (r - r0)).exp();
        energy += d * (1.0 - e) * (1.0 - e);
        let slope = 2.0 * d * a * (1.0 - e) * e;
        for c in 0..3 {
            gradient[3 * i + c] += slope * v[c] / r;
            gradient[3 * j + c] -= slope * v[c] / r;
        }
    }
    PointValue::plain(energy, gradient, None)
}

#[test]
fn rk4_run_matches_multioptpy() {
    let g = golden();
    let run = g.get("rk4").unwrap();
    let pairs: Vec<Vec<f64>> = run
        .get("morse")
        .unwrap()
        .as_array()
        .unwrap()
        .iter()
        .map(floats)
        .collect();
    let start = floats(run.get("start").unwrap());
    let sys = system(&start);
    let settings = IrcSettings {
        step_size: run.get("step_size").unwrap().as_f64().unwrap(),
        max_steps: run.get("max_step").unwrap().as_usize().unwrap(),
        method: "rk4".to_string(),
        ..IrcSettings::default()
    };
    let mut rk4 = IntegratorRegistry::builtin()
        .create(
            "rk4",
            BranchStart {
                x: col(&start),
                hessian: Mat::from_fn(9, 9, |i, j| if i == j { 1.0 } else { 0.0 }),
                settings,
                space: Arc::new(space(&sys, &g)),
                energy: None,
            },
        )
        .unwrap();
    let mut records = Vec::new();
    let mut auxiliary = 0;
    let end = loop {
        match rk4.ask() {
            BranchAction::Finished(end) => break end,
            BranchAction::Evaluate(request) => {
                if request.role == PointRole::Auxiliary {
                    auxiliary += 1;
                }
                if let Some(record) = rk4.tell(&morse(&pairs, &request.x)).unwrap() {
                    records.push(record);
                }
            }
        }
    };
    assert_eq!(end, BranchEnd::MaxSteps);
    let steps: Vec<usize> = records.iter().map(|r| r.step).collect();
    let expected: Vec<usize> = floats(run.get("steps").unwrap())
        .iter()
        .map(|v| *v as usize)
        .collect();
    assert_eq!(steps, expected);
    // Three gradients between two path points from the second point on.
    assert_eq!(auxiliary, 3 * (records.len() - 1));
    let energies: Vec<f64> = records.iter().map(|r| r.energy).collect();
    let difference = largest_difference(&energies, &floats(run.get("energies").unwrap()));
    assert!(difference < 1e-11, "energies: {difference}");
    let rms: Vec<f64> = records.iter().map(|r| r.rms_gradient).collect();
    let difference = largest_difference(&rms, &floats(run.get("rms_gradients").unwrap()));
    assert!(difference < 1e-11, "RMS gradients: {difference}");
    // MultiOptPy's structures are read back from its file (ten decimals in Angstrom).
    let structures = run.get("structures").unwrap().as_array().unwrap();
    assert_eq!(structures.len(), records.len());
    let mut worst = 0.0_f64;
    for (record, reference) in records.iter().zip(structures) {
        let x: Vec<f64> = record.x.iter().copied().collect();
        worst = worst.max(largest_difference(&x, &floats(reference)));
    }
    assert!(worst < 5e-10, "structures: {worst}");
    // The structure changed along the path: the comparison is not of a standstill.
    let first: Vec<f64> = records[0].x.iter().copied().collect();
    let last: Vec<f64> = records[records.len() - 1].x.iter().copied().collect();
    assert!(largest_difference(&first, &last) > 0.2);
}
